t.script:
(function () {
    var box = document.getElementById('o_auth_telegram_inline');
    var btn = document.getElementById('o_auth_telegram_btn');
    if (!box || !btn || !window.fetch || !window.FormData) { return; }
    var fallbackHref = btn.getAttribute('href');
    var redirect = box.getAttribute('data-redirect') || '';
    // this tab's own target, even "none" (several login tabs share one request)
    var completeUrl = '/auth/telegram/complete?redirect=' + encodeURIComponent(redirect);
    // the server renews a link with less than 240 s left: refresh at 210 s
    // left, never follow one with less than 180 s left
    var REFRESH_BEFORE = 210;
    var TAP_MIN = 180;
    var waitEl = document.getElementById('o_auth_telegram_wait');
    var againEl = document.getElementById('o_auth_telegram_again');
    var noMsgEl = document.getElementById('o_auth_telegram_nomsg');
    var codeEl = document.getElementById('o_auth_telegram_code');
    var endedEl = document.getElementById('o_auth_telegram_ended');
    var ready = false;      // the button holds a Telegram link
    var waiting = false;    // polling after a tap (or a resumed login)
    var leaving = false;    // a navigation was started: do nothing more
    var linkDeadline = 0;   // when the current Telegram link expires (ms)
    var linkRef = null;     // fingerprint of the request behind that link
    var waitRef = null;     // fingerprint of the link this tab followed
    var linkAtMax = false;  // the server cannot extend that link any more
    var pollTimer = null;
    var refreshTimer = null;
    var pollGen = 0;
    var prepGen = 0;

    function go(url) {
        leaving = true;
        waiting = false;
        clearTimeout(pollTimer);
        clearTimeout(refreshTimer);
        window.location.href = url;
    }
    function useFallback() {
        ready = false;
        btn.setAttribute('href', fallbackHref);
        btn.removeAttribute('target');
    }
    function linkStale(margin) {
        return Date.now() > linkDeadline - margin * 1000;
    }
    function showEnded(reason) {
        var spans = endedEl.querySelectorAll('span[data-reason]');
        for (var i = 0; i !== spans.length; i++) {
            spans[i].hidden = spans[i].getAttribute('data-reason') !== reason;
        }
        endedEl.hidden = false;
    }
    function stopWaiting() {
        waiting = false;
        waitRef = null;
        linkAtMax = false;
        pollGen++;
        clearTimeout(pollTimer);
        waitEl.hidden = true;
        noMsgEl.hidden = true;
    }
    function schedulePoll(ms) {
        clearTimeout(pollTimer);
        pollTimer = setTimeout(poll, ms);
    }
    function startWaiting() {
        endedEl.hidden = true;
        codeEl.hidden = true;
        waitEl.hidden = false;
        clearTimeout(refreshTimer);
        if (waiting) { return; }
        waiting = true;
        // the link being followed now (a refresh in flight may change
        // linkRef afterwards: polls compare with this one)
        waitRef = linkRef;
        schedulePoll(2000);
    }
    function scheduleRefresh(seconds) {
        clearTimeout(refreshTimer);
        refreshTimer = setTimeout(function () {
            // a hidden tab is refreshed when it becomes visible again
            if (document.visibilityState === 'visible') { prepare(false); }
        }, seconds * 1000);
    }
    function prepare(initial) {
        if (leaving) { return; }
        var gen = ++prepGen;
        var body = new FormData();
        body.append('csrf_token', box.getAttribute('data-csrf'));
        body.append('redirect', redirect);
        // keep-alive of the link this tab is waiting on: never replaced
        body.append('keep', waiting ? '1' : '0');
        fetch('/auth/telegram/prepare', {
            method: 'POST', body: body, credentials: 'same-origin', cache: 'no-store',
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (leaving || gen !== prepGen) { return; }
            if (!data.deeplink) { useFallback(); return; }
            if (data.state === 'confirmed' ? data.needs_code : false) {
                useFallback();
                if (!waiting) { codeEl.hidden = false; }
                return;
            }
            codeEl.hidden = true;
            linkRef = data.ref || null;
            btn.setAttribute('href', data.deeplink);
            btn.setAttribute('target', '_blank');
            btn.setAttribute('rel', 'noopener');
            againEl.setAttribute('href', data.deeplink);
            ready = true;
            linkDeadline = Date.now() + (data.expires_in || 0) * 1000;
            // end of the request's lifetime: no more keep-alives, /status
            // reports 'expired' when it is over
            linkAtMax = waiting ? REFRESH_BEFORE >= (data.expires_in || 0) : false;
            if (initial ? (data.state !== 'pending' || data.opened) : false) {
                // this browser already started a login (page reloaded)
                startWaiting();
                return;
            }
            if (!waiting) { scheduleRefresh(Math.max((data.expires_in || 0) - REFRESH_BEFORE, 30)); }
        }).catch(function () { if (gen === prepGen) { useFallback(); } });
    }
    function poll() {
        if (leaving || !waiting) { return; }
        clearTimeout(pollTimer);
        var gen = ++pollGen;   // only the latest poll may act
        fetch('/auth/telegram/status', {
            credentials: 'same-origin', cache: 'no-store',
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (leaving || !waiting || gen !== pollGen) { return; }
            if (data.state === 'confirmed') {
                // one-time code: typed on the full page
                go(data.needs_code ? fallbackHref : completeUrl);
                return;
            }
            if (data.state === 'done') {
                go(data.redirect || '/web');
                return;
            }
            if (data.state === 'cancelled') {
                if (data.reason === 'no_account') {
                    go('/web/login?telegram_error=no-account');
                    return;
                }
                stopWaiting();
                showEnded(data.reason === 'stale' ? 'expired' : (data.reason || 'user'));
                prepare(false);
                return;
            }
            if (data.state === 'expired' || data.state === 'invalid') {
                stopWaiting();
                showEnded('expired');
                prepare(false);
                return;
            }
            if (data.ref ? (waitRef ? data.ref !== waitRef : false) : false) {
                // another login tab of this browser started a new request:
                // the link this tab opened is gone
                stopWaiting();
                showEnded('expired');
                prepare(false);
                return;
            }
            // pending: tell the customer when the bot could not send the prompt
            noMsgEl.hidden = !data.prompt_missing;
            // not opened in Telegram yet: keep the link alive (renewed in place)
            if (!data.opened ? (linkStale(REFRESH_BEFORE) ? !linkAtMax : false) : false) { prepare(false); }
            schedulePoll(2000);
        }).catch(function () {
            if (!leaving ? (waiting ? gen === pollGen : false) : false) { schedulePoll(4000); }
        });
    }
    function onVisible() {
        if (leaving) { return; }
        if (waiting) { poll(); return; }
        // coming back: pick up the session's current request (another
        // tab may have started a new one) with a fresh link; cheap, the
        // server renews in place and keeps the same token
        prepare(false);
    }

    btn.addEventListener('click', function (ev) {
        if (!ready) { return; }   // the full page /auth/telegram/login
        if (linkStale(TAP_MIN)) {
            // too close to its expiry: the full page renews it first
            ev.preventDefault();
            go(fallbackHref);
            return;
        }
        // the link itself opens Telegram; this page keeps waiting (on
        // the link followed now, also when tapped again while waiting)
        if (waiting) { waitRef = linkRef; }
        startWaiting();
    });
    againEl.addEventListener('click', function (ev) {
        if (linkStale(TAP_MIN)) {
            ev.preventDefault();
            go(fallbackHref);
            return;
        }
        // following the current link again: wait on that one
        if (waiting) { waitRef = linkRef; }
    });
    document.addEventListener('visibilitychange', function () {
        if (document.visibilityState === 'visible') { onVisible(); }
    });
    window.addEventListener('pageshow', function (ev) {
        if (ev.persisted) {
            // restored from the back/forward cache: start over
            leaving = false;
            stopWaiting();
            useFallback();
            prepare(true);
        }
    });
    prepare(true);
})();

(function () {
    var root = document.querySelector('.o_auth_telegram_bot');
    if (!root) { return; }
    var statusEl = document.getElementById('o_auth_telegram_status');
    var openEl = document.getElementById('o_auth_telegram_open');
    var stepsEl = document.getElementById('o_auth_telegram_steps');
    var formEl = document.getElementById('o_auth_telegram_code');
    var noMessageEl = document.getElementById('o_auth_telegram_nomessage');
    var codeShown = !!root.getAttribute('data-needs-code');
    // the request this page shows (another login tab may replace it)
    var pageRef = root.getAttribute('data-ref');
    var delay = 2000;
    if (root.getAttribute('data-ended')) {
        // the request already ended (outcome rendered by the server): nothing to poll
        return;
    }
    function show(id) {
        // a finished request: the deep link / QR code must go with the spinner
        statusEl.hidden = true;
        noMessageEl.hidden = true;
        openEl.hidden = true;
        if (stepsEl) { stepsEl.hidden = true; }
        document.getElementById(id).hidden = false;
    }
    function showCodeForm() {
        if (codeShown) { return; }
        codeShown = true;
        statusEl.hidden = true;
        noMessageEl.hidden = true;
        openEl.hidden = true;
        formEl.hidden = false;
        var input = document.getElementById('o_auth_telegram_code_input');
        if (input) { input.focus(); }
    }
    if (codeShown) {
        var input = document.getElementById('o_auth_telegram_code_input');
        if (input) { input.focus(); }
    }
    function poll() {
        // the request is identified by this browser's session cookie
        fetch('/auth/telegram/status', {
            credentials: 'same-origin', cache: 'no-store',
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (data.state === 'confirmed') {
                if (data.needs_code) {
                    showCodeForm();
                    setTimeout(poll, delay * 5);
                } else {
                    window.location.href = '/auth/telegram/complete';
                }
            } else if (data.state === 'cancelled') {
                if (data.reason === 'no_account') {
                    // same message as the other login methods; retrying cannot help
                    window.location.href = '/web/login?telegram_error=no-account';
                } else if (data.reason === 'taken') {
                    // link flow: the link page has its own message
                    window.location.href = '/auth/telegram/link?error=taken';
                } else {
                    formEl.hidden = true;
                    show({
                        wrong_code: 'o_auth_telegram_wrong_code',
                        conflict: 'o_auth_telegram_conflict',
                        stale: 'o_auth_telegram_expired',
                    }[data.reason] || 'o_auth_telegram_cancelled');
                }
            } else if (data.state === 'done') {
                var link = document.querySelector('#o_auth_telegram_done a');
                if (link) { if (data.redirect) { link.href = data.redirect; } }
                formEl.hidden = true;
                show('o_auth_telegram_done');
            } else if (data.state === 'expired' || data.state === 'invalid') {
                formEl.hidden = true;
                show('o_auth_telegram_expired');
            } else {
                if (data.ref ? (pageRef ? data.ref !== pageRef : false) : false) {
                    // another login tab of this browser started a new request:
                    // this page's link and QR code are gone ("Try again" shows it)
                    formEl.hidden = true;
                    show('o_auth_telegram_expired');
                    return;
                }
                // pending: tell the user when the bot could not send the prompt
                var missing = !!data.prompt_missing;
                noMessageEl.hidden = !missing;
                statusEl.hidden = missing;
                setTimeout(poll, delay);
            }
        }).catch(function () { setTimeout(poll, delay * 2); });
    }
    setTimeout(poll, delay);
})();
